# The .in_labels suggests these are offsets into a function. Let me look up proper function names using nm
aarch64-linux-gnu-nm -C /tmp/monosgen_sym 2>/dev/null | sort | awk '
{
  a = strtonum("0x" $1)
  name = $3
  if (a > 0) {
    if (a <= 0x2f4b20) { s1 = name; o1 = 0x2f4b20 - a; a1 = $1 }
    if (a <= 0x2f4c84) { s2 = name; o2 = 0x2f4c84 - a; a2 = $1 }
    if (a <= 0x2c1a40) { s3 = name; o3 = 0x2c1a40 - a; a3 = $1 }
  }
}
END {
  printf "0x2f4b20: %s+0x%x (fn @ %s)\n", s1, o1, a1
  printf "0x2f4c84: %s+0x%x (fn @ %s)\n", s2, o2, a2
  printf "0x2c1a40: %s+0x%x (fn @ %s)\n", s3, o3, a3
}'

