arguments.command:
# Let's check if these SGen worker addresses have any DWARF info by looking for subprograms near them
aarch64-linux-gnu-readelf --debug-dump=info /tmp/monosgen_sym 2>/dev/null | \
  grep -E "DW_AT_(low_pc|high_pc|name)" | \
  awk '
/DW_AT_name/ { name=$NF }
/DW_AT_low_pc/ { low=strtonum($NF) }
/DW_AT_high_pc/ { 
  high=$NF
  if (high ~ /^0x/) high=strtonum(high); else high=low+strtonum(high)
  if ((low <= 0x2f4b20 && high > 0x2f4b20) || (low <= 0x2f4c84 && high > 0x2f4c84) || (low <= 0x2c1a40 && high > 0x2c1a40)) {
    printf "0x%x-0x%x: %s\n", low, high, name
  }
}' | head -20

